def fetch_binance() -> dict[str, Any]:
    headers = {
        **HEADERS,
        "Accept": "application/json",
        "clienttype": "web",
        "lang": "zh-CN",
        "bnc-location": "CN",
        "Referer": "https://www.binance.com/zh-CN/markets/trading_data/rankings",
    }
    hot_payload = requests.get(
        "https://www.binance.com/bapi/composite/v1/public/market/hot-coins",
        params={"currency": "USD", "type": "1"},
        headers=headers,
        timeout=15,
    ).json()
    product_payload = requests.get(
        "https://www.binance.com/bapi/asset/v2/public/asset-service/product/get-products?includeEtf=true",
        headers=headers,
        timeout=20,
    ).json()
    products = {item.get("s"): item for item in product_payload.get("data", [])}
    top = [
        item
        for item in hot_payload.get("data", [])
        if item.get("assetCode") and not is_excluded_crypto_asset(item.get("assetCode"))
    ][:10]
    rows = []
    for rank, item in enumerate(top, 1):
        symbol = item.get("assetCode", "")
        product = products.get(f"{symbol}USDT") or {}
        last = safe_float(product.get("c"))
        open_price = safe_float(product.get("o"))
        change = ((last - open_price) / open_price * 100) if open_price else 0
        quote_volume = safe_float(product.get("qv"))
        rows.append(
            {
                "rank": rank,
                "symbol": symbol,
                "name": item.get("assetName") or f"{symbol}/USDT",
                "icon": item.get("logoUrl") or crypto_icon_url(symbol),
                "price": price_usd(last),
                "change": pct(change),
                "heat": max(1, round((len(top) - rank + 1) / max(len(top), 1) * 100)),
                "amount": quote_volume,
                "turnover": money_usd(quote_volume) if quote_volume else "官网热榜",
                "tags": ["官网热门币种", "Binance"],
                "note": f"最新价 {last:g}" if last else "官网热门榜",
            }
        )
    return source_template(
        id="binance",
        group="crypto",
        title="Binance 热门币种",
        subtitle="官网 trading_data/rankings 热门币种，已过滤稳定币",
        accent="#f4b740",
        source_label="BN",
        source_name="Binance bapi hot-coins",
        rows=rows,
    )


BINANCE_WALLET_HOT_PERIODS = {
    "5m": {"api": 20, "label": "5 分钟", "change": "percentChange5m", "volume": "volume5m"},
    "1h": {"api": 30, "label": "1 小时", "change": "percentChange1h", "volume": "volume1h"},
    "4h": {"api": 40, "label": "4 小时", "change": "percentChange4h", "volume": "volume4h"},
    "24h": {"api": 50, "label": "24 小时", "change": "percentChange24h", "volume": "volume24h"},
}
BINANCE_WALLET_CHAIN_META = {
    "1": ("Ethereum", "eth"),
    "56": ("BSC", "bsc"),
    "8453": ("Base", "base"),
    "4663": ("Robinhood", "robinhood"),
    "CT_501": ("Solana", "sol"),
}


def normalize_binance_wallet_hot_period(value: Any) -> str:
    period = str(value or "24h").strip().lower()
    return period if period in BINANCE_WALLET_HOT_PERIODS else "24h"


def binance_wallet_icon_url(value: Any) -> str:
    icon = str(value or "").strip()
    if not icon:
        return ""
    if icon.startswith("//"):
        return f"https:{icon}"
    if icon.startswith("/"):
        return f"https://bin.bnbstatic.com{icon}"
    return icon


def binance_wallet_token_url(chain_id: Any, contract_address: Any) -> str:
    contract = str(contract_address or "").strip()
    _, route_chain = BINANCE_WALLET_CHAIN_META.get(str(chain_id or ""), ("", ""))
    if not contract or not route_chain:
        return "https://web3.binance.com/en/markets"
    return f"https://web3.binance.com/en/token/{route_chain}/{quote(contract, safe='')}"


def binance_wallet_hot_source_from_payload(payload: dict[str, Any], period: Any = "24h") -> dict[str, Any]:
    normalized_period = normalize_binance_wallet_hot_period(period)
    config = BINANCE_WALLET_HOT_PERIODS[normalized_period]
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    tokens = data.get("tokens") if isinstance(data.get("tokens"), list) else []
    rows: list[dict[str, Any]] = []
    for raw in tokens:
        if not isinstance(raw, dict):
            continue
        raw_symbol = clean_feed_text(raw.get("symbol") or raw.get("tokenSymbol"), 100)
        # Wallet rankings contain display symbols written in Chinese and other
        # Unicode scripts. They are valid on-chain assets even though they are
        # not valid centralized-exchange ticker codes.
        symbol = clean_price_watch_symbol(raw_symbol) or raw_symbol
        if not symbol or is_excluded_crypto_asset(clean_price_watch_symbol(raw_symbol) or raw_symbol):
            continue
        chain_id = str(raw.get("chainId") or "").strip()
        chain_label, _ = BINANCE_WALLET_CHAIN_META.get(chain_id, (chain_id or "链上", ""))
        contract = clean_feed_text(raw.get("contractAddress"), 128)
        price = safe_float(raw.get("price"), 0)
        change = safe_float(raw.get(config["change"]), 0)
        volume = safe_float(raw.get(config["volume"]), 0)
        liquidity = safe_float(raw.get("liquidity"), 0)
        market_cap = safe_float(raw.get("marketCap"), 0)
        holders = int(safe_float(raw.get("holders"), 0))
        rank = len(rows) + 1
        rows.append({
            "rank": rank,
            "symbol": symbol,
            "name": clean_feed_text(raw.get("name") or raw.get("tokenName") or symbol, 100),
            "icon": binance_wallet_icon_url(raw.get("icon") or raw.get("logo")),
            "price": price_usd(price) if price > 0 else "--",
            "change": pct(change),
            "heat": max(1, round((10 - rank + 1) / 10 * 100)),
            "amount": volume,
            "turnover": f"{config['label']}成交 {money_usd(volume)}" if volume > 0 else f"{config['label']}热榜",
            "metricLabel": money_usd(volume) if volume > 0 else "--",
            "tags": ["币安钱包热门", chain_label, config["label"]],
            "note": " · ".join(part for part in (
                f"流动性 {money_usd(liquidity)}" if liquidity > 0 else "",
                f"市值 {money_usd(market_cap)}" if market_cap > 0 else "",
                f"持币 {holders:,}" if holders > 0 else "",
            ) if part) or "Binance Wallet 链上热门",
            "chain": chain_id,
            "chainLabel": chain_label,
            "contractAddress": contract,
            "liquidity": liquidity,
            "marketCap": market_cap,
            "holders": holders,
            "url": binance_wallet_token_url(chain_id, contract),
        })
        if len(rows) >= 10:
            break
    source = source_template(
        id="binance-wallet-hot",
        group="crypto",
        title="币安钱包热门榜",
        subtitle=f"Binance Wallet 链上热门 · 当前观察 {config['label']}",
        accent="#f4b740",
        source_label="BW",
        source_name="Binance Wallet unified token rank",
        rows=rows,
        status="ok" if rows else "unavailable",
        empty_title="币安钱包热门榜当前为空",
        empty_message="币安钱包热门接口暂时没有返回可展示标的，后台会继续重试并保留上次成功数据。",
    )
    source.update({
        "period": normalized_period,
        "periodLabel": config["label"],
        "periodOptions": [
            {"value": key, "label": value["label"]}
            for key, value in BINANCE_WALLET_HOT_PERIODS.items()
        ],
    })
    # A non-default wallet period is loaded through its own endpoint and is not
    # guaranteed to exist in /api/market-hot's score lookup. Decorate these rows
    # directly so 5m/1h/4h/24h all have a narrative score of their own.
    narrative_period = "1h" if normalized_period in {"5m", "1h"} else "6h" if normalized_period == "4h" else "24h"
    return market_narrative_decorate_source(source, period=narrative_period)


def binance_wallet_4h_structure_identity(row: dict[str, Any]) -> str:
    chain = clean_feed_text(row.get("chain") or row.get("chainId"), 40).lower()
    contract = clean_feed_text(row.get("contractAddress"), 180).lower()
    if contract:
        return js_stable_key("contract", chain, contract)
    return js_stable_key("symbol", chain, clean_feed_text(row.get("symbol") or row.get("name"), 100).casefold())


def record_binance_wallet_4h_structure_source(
    source: dict[str, Any], *, now_ms: int | None = None
) -> list[dict[str, Any]]:
    """Persist every live 4h-wallet ranking appearance for the rolling structure pool."""
    rows = source.get("rows") if isinstance(source.get("rows"), list) else []
    if normalize_binance_wallet_hot_period(source.get("period")) != "4h" or not rows:
        return []
    observed_at = int(now_ms or time.time() * 1000)
    cutoff = observed_at - BINANCE_WALLET_4H_STRUCTURE_RETENTION_SECONDS * 1000
    with BINANCE_WALLET_4H_STRUCTURE_LOCK:
        payload = read_json_cache(BINANCE_WALLET_4H_STRUCTURE_PATH)
        stored = payload.get("items") if isinstance(payload.get("items"), list) else []
        by_identity = {
            str(item.get("identity") or binance_wallet_4h_structure_identity(item)): dict(item)
            for item in stored
            if isinstance(item, dict) and int(safe_float(item.get("lastSeenAt"), 0)) >= cutoff
        }
        for raw in rows:
            if not isinstance(raw, dict):
                continue
            identity = binance_wallet_4h_structure_identity(raw)
            if not identity:
                continue
            previous = by_identity.get(identity, {})
            by_identity[identity] = {
                "identity": identity,
                "symbol": clean_feed_text(raw.get("symbol") or raw.get("name"), 100),
                "name": clean_feed_text(raw.get("name") or raw.get("symbol"), 100),
                "icon": clean_feed_text(raw.get("icon"), 600),
                "chain": clean_feed_text(raw.get("chain"), 40),
                "chainLabel": clean_feed_text(raw.get("chainLabel"), 40),
                "contractAddress": clean_feed_text(raw.get("contractAddress"), 180),
                "url": clean_feed_text(raw.get("url"), 600),
                "walletHotRank": int(safe_float(raw.get("rank"), 0)),
                "walletHeat": safe_float(raw.get("heat"), 0),
                "wallet4hVolumeUsd": round(max(0.0, safe_float(raw.get("amount"), 0)), 2),
                "liquidity": round(max(0.0, safe_float(raw.get("liquidity"), 0)), 2),
                "firstSeenAt": int(safe_float(previous.get("firstSeenAt"), 0)) or observed_at,
                "lastSeenAt": observed_at,
                "expiresAt": observed_at + BINANCE_WALLET_4H_STRUCTURE_RETENTION_SECONDS * 1000,
                "source": "币安钱包4小时热门榜",
            }
        items = sorted(
            by_identity.values(),
            key=lambda item: (int(safe_float(item.get("lastSeenAt"), 0)), -int(safe_float(item.get("walletHotRank"), 999))),
            reverse=True,
        )[:3000]
        write_json_cache(BINANCE_WALLET_4H_STRUCTURE_PATH, {
            "updatedAt": observed_at,
            "retentionDays": BINANCE_WALLET_4H_STRUCTURE_RETENTION_SECONDS // (24 * 60 * 60),
            "items": items,
        })
    return items


def fetch_binance_wallet_hot(period: Any = "24h") -> dict[str, Any]:
    normalized_period = normalize_binance_wallet_hot_period(period)
    config = BINANCE_WALLET_HOT_PERIODS[normalized_period]
    body = {
        "rankType": 10,
        "period": config["api"],
        "sortBy": 1,
        "orderAsc": False,
        "page": 1,
        "size": 20,
    }
    headers = {
        **HEADERS,
        "Accept": "application/json",
        "Accept-Encoding": "identity",
        "Content-Type": "application/json",
        "User-Agent": "binance-web3/2.1 (Xingyun Market Dashboard)",
        "Referer": "https://web3.binance.com/en/markets",
    }
    errors: list[str] = []
    path = "/bapi/defi/v1/public/wallet-direct/buw/wallet/market/token/pulse/unified/rank/list/ai"
    for host in ("https://web3.binance.com", "https://www.binance.com"):
        try:
            response = requests.post(f"{host}{path}", json=body, headers=headers, timeout=(6, 20))
            response.raise_for_status()
            payload = response.json()
            if not isinstance(payload, dict) or payload.get("success") is False:
                raise RuntimeError(clean_feed_text((payload or {}).get("message") or (payload or {}).get("msg") or "invalid response", 160))
            source = binance_wallet_hot_source_from_payload(payload, normalized_period)
            if source_has_rows(source):
                source["sourceName"] = f"Binance Wallet unified token rank · {urlparse(host).netloc}"
                if normalized_period == "4h":
                    record_binance_wallet_4h_structure_source(source)
                return source
            errors.append(f"{urlparse(host).netloc}: empty rank")
        except Exception as exc:
            errors.append(f"{urlparse(host).netloc}: {safe_error_text(str(exc))}")
    raise RuntimeError("；".join(errors[-2:]) or "Binance Wallet 热门榜请求失败")


def binance_wallet_hot_source(period: Any = "24h", *, force_refresh: bool = False) -> dict[str, Any]:
    normalized_period = normalize_binance_wallet_hot_period(period)
    cache_key = f"binance-wallet-hot-{normalized_period}"
    if force_refresh:
        CACHE.pop(cache_key, None)
    source = cached_or_fallback_source(
        cache_key,
        lambda: fetch_binance_wallet_hot(normalized_period),
        api_key="market-hot",
        fallback_group="crypto",
        error_title="币安钱包热门榜",
        error_subtitle=f"Binance Wallet {BINANCE_WALLET_HOT_PERIODS[normalized_period]['label']} 热门数据源请求失败",
        error_empty_title="币安钱包热门榜暂时不可用",
    )
    return {
        **source,
        "id": "binance-wallet-hot",
        "title": "币安钱包热门榜",
        "sourceLabel": "BW" if source.get("sourceLabel") == "ERR" else source.get("sourceLabel") or "BW",
        "period": normalized_period,
        "periodLabel": BINANCE_WALLET_HOT_PERIODS[normalized_period]["label"],
        "periodOptions": [
            {"value": key, "label": value["label"]}
            for key, value in BINANCE_WALLET_HOT_PERIODS.items()
        ],
    }


def sync_binance_wallet_4h_structure_history(*, force_refresh: bool = False) -> None:
    global BINANCE_WALLET_4H_STRUCTURE_LAST_SYNC_AT, BINANCE_WALLET_4H_STRUCTURE_ACTIVE
    now = time.time()
    if not force_refresh and now - BINANCE_WALLET_4H_STRUCTURE_LAST_SYNC_AT < BINANCE_WALLET_4H_STRUCTURE_SYNC_SECONDS:
        return
    BINANCE_WALLET_4H_STRUCTURE_LAST_SYNC_AT = now
    binance_wallet_hot_source("4h", force_refresh=True)
    BINANCE_WALLET_4H_STRUCTURE_ACTIVE = True


def binance_wallet_4h_structure_rows(*, now_ms: int | None = None) -> list[dict[str, Any]]:
    current_ms = int(now_ms or time.time() * 1000)
    cutoff = current_ms - BINANCE_WALLET_4H_STRUCTURE_RETENTION_SECONDS * 1000
    with BINANCE_WALLET_4H_STRUCTURE_LOCK:
        payload = read_json_cache(BINANCE_WALLET_4H_STRUCTURE_PATH)
    rows = [
        dict(item)
        for item in (payload.get("items") if isinstance(payload.get("items"), list) else [])
        if isinstance(item, dict) and int(safe_float(item.get("lastSeenAt"), 0)) >= cutoff
    ]
    # The live-source flag is process-local, while the 30-day membership pool
    # is intentionally persistent. Hydrate valid saved rows immediately after
    # a restart so structure monitoring does not depend on somebody opening the
    # Binance Wallet ranking page first.
    if not BINANCE_WALLET_4H_STRUCTURE_ACTIVE and not rows:
        return []
    rows.sort(key=lambda item: (
        int(safe_float(item.get("lastSeenAt"), 0)),
        -int(safe_float(item.get("walletHotRank"), 999)),
    ), reverse=True)
    return rows


def okx_rank_change(value: Any) -> float:
    change = safe_float(value)
    return change * 100 if -1.5 <= change <= 1.5 else change


def okx_symbol_from_item(item: dict[str, Any]) -> str:
    symbol = str(
        item.get("ccyV2")
        or item.get("ccy")
        or item.get("baseCcy")
        or item.get("instFamily")
        or item.get("coin")
        or ""
    ).upper()
    if not symbol:
        inst_id = str(item.get("instId") or item.get("instIdV2") or item.get("uly") or "").upper()
        symbol = re.sub(r"[-_](USDT|USDC|USD)([-_](SWAP|FUTURES))?$", "", inst_id)
        symbol = symbol.split("-")[0].split("_")[0]
    return symbol.replace("/USDT", "").replace("-USDT", "").strip()


def parse_okx_rank_rows(items: list[Any], *, tag: str = "期货热榜") -> list[dict[str, Any]]:
    dict_items = [item for item in items if isinstance(item, dict)]
    max_hot = max(
        [
            safe_float(
                item.get("hotIndex")
                or item.get("rankIndex")
                or item.get("weight")
                or (len(dict_items) - index)
            )
            for index, item in enumerate(dict_items)
        ]
        or [1]
    )
    rows: list[dict[str, Any]] = []
    for rank, item in enumerate(dict_items, 1):
        symbol = okx_symbol_from_item(item)
        if not symbol or is_excluded_crypto_asset(symbol):
            continue
        last = safe_float(
            item.get("lastPrice")
            or item.get("last")
            or item.get("lastPx")
            or item.get("price")
            or item.get("markPx")
        )
        change = okx_rank_change(item.get("changePerDay24h") or item.get("changePerV2") or item.get("changePer") or item.get("chg"))
        turnover = safe_float(
            item.get("turnOver24h")
            or item.get("turnOver")
            or item.get("turnover")
            or item.get("turnOverV2")
            or item.get("quoteVolume24h")
            or item.get("volCcy24h")
            or item.get("volUsd24h")
            or item.get("amount")
        )
        hot_index = safe_float(item.get("hotIndex") or item.get("rankIndex") or item.get("weight") or (len(dict_items) - rank + 1))
        rows.append(
            {
                "rank": len(rows) + 1,
                "symbol": symbol,
                "name": item.get("instId") or item.get("instIdV2") or f"{symbol}-USDT-SWAP",
                "icon": item.get("icon") or item.get("logoUrl") or item.get("coinIcon") or crypto_icon_url(symbol),
                "price": price_usd(last),
                "change": pct(change),
                "heat": max(1, min(100, round(hot_index / max(max_hot, 1) * 100))),
                "amount": turnover,
                "turnover": money_usd(turnover) if turnover else "官网热榜",
                "tags": [tag, "OKX"],
                "note": f"最新价 {last:g}" if last else "OKX 合约热门榜",
            }
        )
        if len(rows) >= 10:
            break
    return rows


def fetch_okx_futures_public_ticker_rows(mode: str = "hot") -> tuple[list[dict[str, Any]], str]:
    payload = requests.get(
        "https://www.okx.com/api/v5/market/tickers",
        params={"instType": "SWAP"},
        headers={"User-Agent": HEADERS["User-Agent"], "Accept": "application/json"},
        timeout=18,
    ).json()
    if str(payload.get("code", "0")) != "0":
        raise RuntimeError(str(payload.get("msg") or payload.get("code") or "OKX ticker error"))

    candidates: list[dict[str, Any]] = []
    for item in payload.get("data", []) or []:
        if not isinstance(item, dict):
            continue
        inst_id = str(item.get("instId") or "").upper()
        parts = inst_id.split("-")
        if len(parts) < 3 or parts[1] != "USDT" or parts[-1] != "SWAP":
            continue
        asset = parts[0]
        if not asset or is_excluded_crypto_asset(asset):
            continue
        last = safe_float(item.get("last"))
        if not last:
            continue
        open_price = safe_float(item.get("open24h"))
        change = change_from_open(last, open_price)
        volume_base = safe_float(item.get("volCcy24h")) or safe_float(item.get("vol24h"))
        turnover = safe_float(item.get("volUsd24h")) or (last * volume_base if volume_base else 0)
        if mode == "gainers" and change <= 0:
            continue
        momentum_boost = 1 + min(abs(change), 80) / 100
        score = turnover * momentum_boost
        candidates.append(
            {
                "asset": asset,
                "instId": inst_id,
                "last": last,
                "change": change,
                "turnover": turnover,
                "score": score,
            }
        )

    if mode == "gainers":
        candidates.sort(key=lambda item: (safe_float(item.get("change")), safe_float(item.get("turnover"))), reverse=True)
        tag = "OKX 合约涨幅榜"
        detail = "public /api/v5/market/tickers SWAP 24h gainers"
    elif mode == "turnover":
        candidates.sort(key=lambda item: safe_float(item.get("turnover")), reverse=True)
        tag = "OKX 合约成交额榜"
        detail = "public /api/v5/market/tickers SWAP 24h turnover"
    else:
        candidates.sort(key=lambda item: safe_float(item.get("score")), reverse=True)
        tag = "OKX 合约公开热度"
        detail = "public /api/v5/market/tickers SWAP hot fallback"

    top = candidates[:10]
    max_score = max([safe_float(item.get("score" if mode == "hot" else "turnover")) for item in top] or [1])
    rows: list[dict[str, Any]] = []
    for item in top:
        heat_basis = safe_float(item.get("score" if mode == "hot" else "turnover"))
        rows.append(
            {
                "rank": len(rows) + 1,
                "symbol": item["asset"],
                "name": item["instId"],
                "icon": crypto_icon_url(item["asset"]),
                "price": price_usd(item["last"]),
                "change": pct(item["change"]),
                "heat": max(1, min(100, round(heat_basis / max(max_score, 1) * 100))),
                "amount": item["turnover"],
                "turnover": money_usd(item["turnover"]) if item["turnover"] else "--",
                "tags": ["OKX", tag],
                "note": f"24h turnover {money_usd(item['turnover']) if item['turnover'] else '--'} · 24h {pct(item['change'])}",
                "url": f"https://www.okx.com/zh-hans/trade-swap/{item['instId'].lower()}",
            }
        )
    return rows, detail


def fetch_okx_futures_hot_from_public_tickers() -> tuple[list[dict[str, Any]], str]:
    return fetch_okx_futures_public_ticker_rows("hot")


def fetch_okx_futures_turnover_from_public_tickers() -> tuple[list[dict[str, Any]], str]:
    return fetch_okx_futures_public_ticker_rows("turnover")


def fetch_okx_futures_ssr_rank() -> tuple[list[dict[str, Any]], str]:
    headers = {
        **okx_web_headers(),
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    }
    pages = [
        ("https://www.okx.com/zh-hans/markets/rankings/futures/hot-crypto", "official SSR hot-crypto detail"),
        ("https://www.okx.com/zh-hans/markets/rankings/futures", "official SSR hot-crypto overview"),
    ]
    last_detail = "official SSR appState missing"
    for url, label in pages:
        response = requests.get(url, headers=headers, timeout=22)
        response.raise_for_status()
        app_state = BeautifulSoup(response.text, "html.parser").find("script", {"id": "appState"})
        raw_state = (app_state.string or app_state.get_text()) if app_state else ""
        if not raw_state:
            match = re.search(r'<script[^>]+id=["\']appState["\'][^>]*>(.*?)</script>', response.text, re.I | re.S)
            raw_state = html.unescape(match.group(1).strip()) if match else ""
        if not raw_state:
            last_detail = f"{label} appState missing"
            continue

        state = json.loads(raw_state)
        rank_store = (
            state.get("appContext", {})
            .get("initialProps", {})
            .get("ssrData", {})
            .get("rankStore", {})
        )
        hot_block = rank_store.get("rankData", {}).get("hot-crypto", {})
        raw_items = hot_block.get("data") or []
        rows = parse_okx_rank_rows(raw_items, tag="OKX official hot")
        page_size = hot_block.get("pageSize") or len(raw_items) or len(rows)
        detail = f"{label} pageSize={page_size}"
        if rows:
            return rows, detail
        last_detail = f"{detail} empty"
    return [], last_detail


def okx_items_from_payload(payload: dict[str, Any]) -> list[Any]:
    data_block = payload.get("data") or {}
    if isinstance(data_block, dict):
        for key in ("data", "hot-rank", "hotRank", "futuresHotRank", "rankList", "list"):
            value = data_block.get(key)
            if isinstance(value, list):
                return value
        return []
    if isinstance(data_block, list):
        if len(data_block) == 1 and isinstance(data_block[0], dict):
            for key in ("hot-rank", "hotRank", "futuresHotRank", "rankList", "list", "data"):
                value = data_block[0].get(key)
                if isinstance(value, list):
                    return value
        return data_block
    return []


