def deepseek_empty_insight_text(value: str) -> bool:
    text = clean_feed_text(value, 80)
    if not text:
        return False
    compact = re.sub(r"\s+", "", text)
    return any(re.search(pattern, compact, re.I) for pattern in DEEPSEEK_EMPTY_INSIGHT_PATTERNS)


